STORAGES = {
    "default": {
        "BACKEND": "storages.backends.s3.S3Storage",
        "OPTIONS": {
            "bucket_name": os.getenv("S3_BUCKET", "praxis"),
            "endpoint_url": os.getenv("S3_ENDPOINT") or None,
            "region_name": os.getenv("S3_REGION", "us-east-1"),
            "access_key": os.getenv("S3_ACCESS_KEY") or None,
            "secret_key": os.getenv("S3_SECRET_KEY") or None,
            "default_acl": None,
            "querystring_auth": True,
        },
    },
    "staticfiles": {"BACKEND": "django.contrib.staticfiles.storage.StaticFilesStorage"},
}
# @praxis:settings

storageClient, err := storage.Open(ctx, os.Getenv("S3_ENDPOINT"), os.Getenv("S3_REGION"), os.Getenv("S3_ACCESS_KEY"), os.Getenv("S3_SECRET_KEY"))
if err != nil {
	log.Error("object storage startup failed", "error", err)
	os.Exit(1)
}
if err := storage.Check(ctx, storageClient, os.Getenv("S3_BUCKET")); err != nil {
	log.Error("object storage readiness failed", "error", err)
	os.Exit(1)
}
// @praxis:startup
